(5155765, 750726, 70000, '<td valign="top">well composed, the blurred edges are really distracting but the colors and clarity in the middle are lovely</td>', 'well composed, the blurred edges are really distracting but the colors and clarity in the middle are lovely', '2008-12-29 00:05:18.000000', NULL, 1),
(5155768, 750787, 48389, '<td valign="top">Excellent composition, I love the angle you have chosen to place the model in the frame. Background really compliments the subject and I really like how soft her skin looks. The eyes are troubling me a little, I really like the makeup that draws you into them but feel your editing may be a little too much on the eyes themselves...hope that makes sense?! Still a 9 from me :o)</td>', 'Excellent composition, I love the angle you have chosen to place the model in the frame. Background really compliments the subject and I really like how soft her skin looks. The eyes are troubling me a little, I really like the makeup that draws you into them but feel your editing may be a little too much on the eyes themselves...hope that makes sense?! Still a 9 from me :o)', '2008-12-29 00:05:59.000000', NULL, 1),
(5155774, 750760, 70000, '<td valign="top">The moment captured is nice, but the photo is really oversaturated and the artificial blur really detracts from the beauty of the moment in my opinion.</td>', 'The moment captured is nice, but the photo is really oversaturated and the artificial blur really detracts from the beauty of the moment in my opinion.', '2008-12-29 00:07:49.000000', NULL, 1),
