(5155952, 750605, 96915, '<td valign="top">I think the composition could have been simplified by moving the chair out of the background.</td>', 'I think the composition could have been simplified by moving the chair out of the background.', '2008-12-29 02:12:17.000000', NULL, 1),
(5155971, 750463, 28742, '<td valign="top">Yeah, baby!! :)</td>', 'Yeah, baby!! :)', '2008-12-29 02:52:18.000000', NULL, 1),
