(5156094, 750463, 15711, '<td valign="top">That is so awesome!!!!</td>', 'That is so awesome!!!!', '2008-12-29 08:21:07.000000', NULL, 1),
(5156095, 750539, 15711, '<td valign="top">Nicely shot.  Reminds me of something in an upscale gourmet magazine.  I wish that the reflection of the rice at the bottom wasn''t "cut off" if that makes sense. 7</td>', 'Nicely shot.  Reminds me of something in an upscale gourmet magazine.  I wish that the reflection of the rice at the bottom wasn''t "cut off" if that makes sense. 7', '2008-12-29 08:23:08.000000', NULL, 1),
