(5156100, 750787, 15711, '<td valign="top">Beautiful but her skin seems a touch over processed (maybe Neat Image?)with her eyes  being over sharp.  I love the bokeh and the diagonal line created by the tilt of her and her arm.</td>', 'Beautiful but her skin seems a touch over processed (maybe Neat Image?)with her eyes  being over sharp.  I love the bokeh and the diagonal line created by the tilt of her and her arm.', '2008-12-29 08:25:00.000000', NULL, 1),
(5156102, 750118, 15711, '<td valign="top">Very artful.</td>', 'Very artful.', '2008-12-29 08:27:03.000000', NULL, 1),
(5156103, 750592, 15711, '<td valign="top">Lovely and subtle.</td>', 'Lovely and subtle.', '2008-12-29 08:28:23.000000', NULL, 1),
(5156104, 750812, 15711, '<td valign="top">I really like the contrast of colors.  Different and artful.</td>', 'I really like the contrast of colors.  Different and artful.', '2008-12-29 08:28:42.000000', NULL, 1),
(5156120, 750605, 93756, '<td valign="top">Really nice "food" photo - I want to eat the food! Doesn''t scream Asia but meets the challenge, probably needs to whisper Asia a little more to score higher in this one.</td>', 'Really nice "food" photo - I want to eat the food! Doesn''t scream Asia but meets the challenge, probably needs to whisper Asia a little more to score higher in this one.', '2008-12-29 08:48:14.000000', NULL, 1),
(5156121, 750311, 93756, '<td valign="top">Very nice portrait - you''ve really flattered your subject. She should be happy with it.</td>', 'Very nice portrait - you''ve really flattered your subject. She should be happy with it.', '2008-12-29 08:56:06.000000', NULL, 1),
(5156122, 750175, 93756, '<td valign="top">Just wish those feathers weren''t cut off. Great find.</td>', 'Just wish those feathers weren''t cut off. Great find.', '2008-12-29 08:57:41.000000', NULL, 1),
(5156125, 750772, 93756, '<td valign="top">Best of the "statue" shots. You showed some atmosphere by finding a statue in a real place instead of a studio shot. Be careful with the crop at the top of his head. You could have adjusted the white balance more away from yellow.</td>', 'Best of the "statue" shots. You showed some atmosphere by finding a statue in a real place instead of a studio shot. Be careful with the crop at the top of his head. You could have adjusted the white balance more away from yellow.', '2008-12-29 09:00:08.000000', NULL, 1),
(5156126, 750791, 93756, '<td valign="top">Nice colors just a little boring in the framing.</td>', 'Nice colors just a little boring in the framing.', '2008-12-29 09:00:35.000000', NULL, 1),
(5156127, 750813, 93756, '<td valign="top">You get an extra point for originality. Just wish the leaf going into the snow was more clear since that''s where the eye goes, more DOF would have worked here.</td>', 'You get an extra point for originality. Just wish the leaf going into the snow was more clear since that''s where the eye goes, more DOF would have worked here.', '2008-12-29 09:02:17.000000', NULL, 1),
