(5158170, 750311, 3087, '<td valign="top">A beautiful portrait, with a very natural and sweet smile. You must be pleased to bits with it.</td>', 'A beautiful portrait, with a very natural and sweet smile. You must be pleased to bits with it.', '2008-12-30 16:02:40.000000', NULL, 1),
(5158171, 750054, 3087, '<td valign="top">Captures Hanae''s beautiful features and delicate bone structure but not her essential warmth and inner joy.</td>', 'Captures Hanae''s beautiful features and delicate bone structure but not her essential warmth and inner joy.', '2008-12-30 16:03:17.000000', NULL, 1),
(5158174, 750516, 3087, '<td valign="top">I really like this street photograph. Much to look at and to wonder about.</td>', 'I really like this street photograph. Much to look at and to wonder about.', '2008-12-30 16:04:18.000000', NULL, 1),
(5158175, 750787, 3087, '<td valign="top">She''s absolutely beautiful but her eyes seem to be held unnaturally wide open which lends the image a (presumably unintended) scary air. Lighting is lovely, not sure about the quirky angle; it''s something that I''ve seen work well but doesn''t work for me for this pose.</td>', 'She''s absolutely beautiful but her eyes seem to be held unnaturally wide open which lends the image a (presumably unintended) scary air. Lighting is lovely, not sure about the quirky angle; it''s something that I''ve seen work well but doesn''t work for me for this pose.', '2008-12-30 16:05:53.000000', NULL, 1),
(5158178, 750454, 3087, '<td valign="top">I like that top down perspective and the direct eye contact. Her bright coloured clothing works well with the bright fruit.</td>', 'I like that top down perspective and the direct eye contact. Her bright coloured clothing works well with the bright fruit.', '2008-12-30 16:06:53.000000', NULL, 1),
(5158180, 750726, 3087, '<td valign="top">Nice composition and nicely lit too.</td>', 'Nice composition and nicely lit too.', '2008-12-30 16:07:11.000000', NULL, 1),
