(5158448, 750718, 96511, '<td valign="top">What a fantastic capture!  Sky is lovely and the little guy is quite impressive!</td>', 'What a fantastic capture!  Sky is lovely and the little guy is quite impressive!', '2008-12-30 19:19:42.000000', NULL, 1),
(5158550, 750644, 96751, '<td valign="top">I love the shape of the roofline, but find the dark central object distracting, and the colors overblown.</td>', 'I love the shape of the roofline, but find the dark central object distracting, and the colors overblown.', '2008-12-30 20:35:11.000000', NULL, 1),
(5158552, 750787, 96751, '<td valign="top">Um, those eyes are really disturbing...</td>', 'Um, those eyes are really disturbing...', '2008-12-30 20:35:32.000000', NULL, 1),
(5158553, 750386, 96751, '<td valign="top">So close!  A less complicated background or jacket would have improved this adorable shot.</td>', 'So close!  A less complicated background or jacket would have improved this adorable shot.', '2008-12-30 20:36:18.000000', NULL, 1),
(5158554, 750759, 96751, '<td valign="top">Amazing make up and color selection.  The b/w and color contrast really work for this.</td>', 'Amazing make up and color selection.  The b/w and color contrast really work for this.', '2008-12-30 20:37:03.000000', NULL, 1),
(5158555, 750819, 96751, '<td valign="top">Nice composition.  Not sure why it isn''t as strong as it should be.  More dramatic lighting?  More contrast?  Perhaps in B/W, although I love the blue rim.</td>', 'Nice composition.  Not sure why it isn''t as strong as it should be.  More dramatic lighting?  More contrast?  Perhaps in B/W, although I love the blue rim.', '2008-12-30 20:37:52.000000', NULL, 1),
(5158557, 749639, 96751, '<td valign="top">Beautiful blue, nice dramatic lighting, but the subject looks blurred to me.</td>', 'Beautiful blue, nice dramatic lighting, but the subject looks blurred to me.', '2008-12-30 20:38:28.000000', NULL, 1),
(5158559, 750198, 96751, '<td valign="top">Original idea, but shot from a higher angle would have give this a cleaner, more powerful background.</td>', 'Original idea, but shot from a higher angle would have give this a cleaner, more powerful background.', '2008-12-30 20:39:28.000000', NULL, 1),
(5158560, 750726, 96751, '<td valign="top">Nice and sharp, great colors and textures.  I think I can even smell this.</td>', 'Nice and sharp, great colors and textures.  I think I can even smell this.', '2008-12-30 20:39:58.000000', NULL, 1),
(5158577, 750727, 96751, '<td valign="top">Lovely tones, shapes, and textures.  A tad flat though.</td>', 'Lovely tones, shapes, and textures.  A tad flat though.', '2008-12-30 20:53:54.000000', NULL, 1),
(5158578, 750477, 96751, '<td valign="top">Strong and bold. Undecided about the tilt.</td>', 'Strong and bold. Undecided about the tilt.', '2008-12-30 20:54:18.000000', NULL, 1),
(5158580, 750771, 96751, '<td valign="top">Nice and simple.  The reflection really works on this.</td>', 'Nice and simple.  The reflection really works on this.', '2008-12-30 20:54:37.000000', NULL, 1),
(5158582, 750683, 96751, '<td valign="top">Awesome macro.  Most original shot of the bunch.  Great use of desaturation.</td>', 'Awesome macro.  Most original shot of the bunch.  Great use of desaturation.', '2008-12-30 20:55:19.000000', NULL, 1),
(5158583, 750730, 96751, '<td valign="top">Great idea.</td>', 'Great idea.', '2008-12-30 20:55:32.000000', NULL, 1),
(5158586, 750781, 96751, '<td valign="top">Gorgeous shot.  Love the detail on the sides and neck feathers.</td>', 'Gorgeous shot.  Love the detail on the sides and neck feathers.', '2008-12-30 20:56:15.000000', NULL, 1),
(5158591, 750777, 96751, '<td valign="top">The left cookie has great shadows while the right one is oddly flat.</td>', 'The left cookie has great shadows while the right one is oddly flat.', '2008-12-30 20:57:02.000000', NULL, 1),
(5158592, 750140, 96751, '<td valign="top">Love the colors but not the composition.</td>', 'Love the colors but not the composition.', '2008-12-30 20:57:15.000000', NULL, 1),
(5158593, 749463, 96751, '<td valign="top">Very nice shot!  Colors, narrow dof, shapes, textures.</td>', 'Very nice shot!  Colors, narrow dof, shapes, textures.', '2008-12-30 20:57:50.000000', NULL, 1),
(5158594, 750655, 96751, '<td valign="top">The rice is a problem for me not enough to make a statement, too much to be ignored but doesn''t really contribute.  Perhaps a single grain?  Or a nice rounded portion?</td>', 'The rice is a problem for me not enough to make a statement, too much to be ignored but doesn''t really contribute.  Perhaps a single grain?  Or a nice rounded portion?', '2008-12-30 20:58:55.000000', NULL, 1),
(5158599, 750702, 96751, '<td valign="top">Very interesting shot.  But the foremost headstone is just too over-contrasty and too white.</td>', 'Very interesting shot.  But the foremost headstone is just too over-contrasty and too white.', '2008-12-30 21:01:33.000000', NULL, 1),
(5158600, 750818, 96751, '<td valign="top">If the objects had not been on the same plane, this would have been a more interesting shot.</td>', 'If the objects had not been on the same plane, this would have been a more interesting shot.', '2008-12-30 21:02:09.000000', NULL, 1),
(5158601, 750813, 96751, '<td valign="top">Very minimalist and Zen.</td>', 'Very minimalist and Zen.', '2008-12-30 21:02:28.000000', NULL, 1),
(5158602, 750789, 96751, '<td valign="top">Excellent shot.  Wonderful subject and mood, great use of b/w</td>', 'Excellent shot.  Wonderful subject and mood, great use of b/w', '2008-12-30 21:02:50.000000', NULL, 1),
(5158604, 750782, 96751, '<td valign="top">Adorable shot but feels a bit shoehorned</td>', 'Adorable shot but feels a bit shoehorned', '2008-12-30 21:03:21.000000', NULL, 1),
(5158605, 750308, 96751, '<td valign="top">Love the dof.  Wish it weren''t tilted.</td>', 'Love the dof.  Wish it weren''t tilted.', '2008-12-30 21:03:39.000000', NULL, 1),
(5158609, 750791, 96751, '<td valign="top">I have one of these!</td>', 'I have one of these!', '2008-12-30 21:04:51.000000', NULL, 1),
(5158610, 750347, 96751, '<td valign="top">What a great shadow puppet.  Lighting is a bit to harsh for this.  Something subtler or more focused would have added drama.</td>', 'What a great shadow puppet.  Lighting is a bit to harsh for this.  Something subtler or more focused would have added drama.', '2008-12-30 21:06:09.000000', NULL, 1),
(5158612, 749773, 96751, '<td valign="top">Low light problems with focus.</td>', 'Low light problems with focus.', '2008-12-30 21:08:03.000000', NULL, 1),
(5158790, 750792, 91663, '<td valign="top">Great texture, but the light''s a little harsh for my tastes.</td>', 'Great texture, but the light''s a little harsh for my tastes.', '2008-12-30 23:29:18.000000', NULL, 1),
(5158793, 750730, 91663, '<td valign="top">I love the frame, and the texture is excellent, but i feel like the thing in the background being framed is too interesting to have this shallow DOF. Perhaps a little more in focus (though not completely).</td>', 'I love the frame, and the texture is excellent, but i feel like the thing in the background being framed is too interesting to have this shallow DOF. Perhaps a little more in focus (though not completely).', '2008-12-30 23:30:14.000000', NULL, 1),
(5158795, 750819, 91663, '<td valign="top">Something about this image is really tearing me in two as to whether I like it or not. It''s so completely lit on all sides that it both a) looks flat and b) looks kinda hip, like a Wes Anderson movie. Or Napoleon Dynamite. 7 for making me think so freakin'' hard.</td>', 'Something about this image is really tearing me in two as to whether I like it or not. It''s so completely lit on all sides that it both a) looks flat and b) looks kinda hip, like a Wes Anderson movie. Or Napoleon Dynamite. 7 for making me think so freakin'' hard.', '2008-12-30 23:32:12.000000', NULL, 1),
(5158796, 750810, 91663, '<td valign="top">Pretty, well-lit, but a little too catalog-y for my tastes. There''s no real life in this, I''m afraid.</td>', 'Pretty, well-lit, but a little too catalog-y for my tastes. There''s no real life in this, I''m afraid.', '2008-12-30 23:32:53.000000', NULL, 1),
(5158799, 750815, 91663, '<td valign="top">If you could get the whole character in focus, that would help a little. <br/> <br/>This image kinda leaves me feeling ''so what?'' The technicals are pretty much there, but I don''t see any real reason for this image to exist. Sorry if that sounds a little harsh, but I like it when an image has a little more...thesis?</td>', 'If you could get the whole character in focus, that would help a little.  This image kinda leaves me feeling ''so what?'' The technicals are pretty much there, but I don''t see any real reason for this image to exist. Sorry if that sounds a little harsh, but I like it when an image has a little more...thesis?', '2008-12-30 23:35:52.000000', NULL, 1),
(5158800, 750820, 91663, '<td valign="top">Fascinating background...like an impressionist painting.</td>', 'Fascinating background...like an impressionist painting.', '2008-12-30 23:36:09.000000', NULL, 1),
(5158803, 750772, 91663, '<td valign="top">The fact that it''s in a shop unfortunately makes me think ''Chinatown'' more than actual Asia. Great texture on the statue though.</td>', 'The fact that it''s in a shop unfortunately makes me think ''Chinatown'' more than actual Asia. Great texture on the statue though.', '2008-12-30 23:37:32.000000', NULL, 1),
(5158804, 750771, 91663, '<td valign="top">Very pretty, though I think the shallow DOF on the end of the sticks doesn''t do a lot for this.</td>', 'Very pretty, though I think the shallow DOF on the end of the sticks doesn''t do a lot for this.', '2008-12-30 23:37:58.000000', NULL, 1),
(5158805, 750773, 91663, '<td valign="top">Great colors, but texturally a little flat.</td>', 'Great colors, but texturally a little flat.', '2008-12-30 23:38:16.000000', NULL, 1),
(5158809, 750334, 91663, '<td valign="top">Excellent lighting and color. Negative space at the top right unfortunately seems a little purposeless.</td>', 'Excellent lighting and color. Negative space at the top right unfortunately seems a little purposeless.', '2008-12-30 23:39:10.000000', NULL, 1),
(5158813, 750319, 91663, '<td valign="top">Maybe a little too much DOF, oddly enough. This image doesn''t seem to have as much depth as it should in my opinion. The colors are a little too homogeneous for me, too...</td>', 'Maybe a little too much DOF, oddly enough. This image doesn''t seem to have as much depth as it should in my opinion. The colors are a little too homogeneous for me, too...', '2008-12-30 23:40:50.000000', NULL, 1),
(5158815, 750308, 91663, '<td valign="top">I like the muted colors and the dutch angle, as well as the shallow DOF. Good job!</td>', 'I like the muted colors and the dutch angle, as well as the shallow DOF. Good job!', '2008-12-30 23:41:27.000000', NULL, 1),
(5158816, 750118, 91663, '<td valign="top">Excellent lighting, expression, composition! Love it.</td>', 'Excellent lighting, expression, composition! Love it.', '2008-12-30 23:41:54.000000', NULL, 1),
(5158817, 750175, 91663, '<td valign="top">This is pretty sweet. The subtle toning, the shadow on his face, the lines in the weapon and his hat. Nice!</td>', 'This is pretty sweet. The subtle toning, the shadow on his face, the lines in the weapon and his hat. Nice!', '2008-12-30 23:42:40.000000', NULL, 1),
(5158818, 750007, 91663, '<td valign="top">Excellent lines, perspective. The colors are a little bland, though...</td>', 'Excellent lines, perspective. The colors are a little bland, though...', '2008-12-30 23:43:08.000000', NULL, 1),
(5158819, 750311, 91663, '<td valign="top">Nice natural looking portrait. Something bothers me a little bit about the direction she''s looking...I think there''s not enough negative space at her right or something...Sorry I can''t put my finger on it, but it''s pretty good otherwise!</td>', 'Nice natural looking portrait. Something bothers me a little bit about the direction she''s looking...I think there''s not enough negative space at her right or something...Sorry I can''t put my finger on it, but it''s pretty good otherwise!', '2008-12-30 23:44:34.000000', NULL, 1),
(5158821, 750777, 91663, '<td valign="top">Hahaha, awesome. I''ll help you get there with a 7, but I have to note it could have been higher with softer light on the cookies.</td>', 'Hahaha, awesome. I''ll help you get there with a 7, but I have to note it could have been higher with softer light on the cookies.', '2008-12-30 23:45:52.000000', NULL, 1),
(5158822, 750477, 91663, '<td valign="top">Woah, that''s some trippy processing, especially on the sky. In fact, the sky''s treatment seems a little too much for the more down-to-earth look and feel of the rest.</td>', 'Woah, that''s some trippy processing, especially on the sky. In fact, the sky''s treatment seems a little too much for the more down-to-earth look and feel of the rest.', '2008-12-30 23:47:13.000000', NULL, 1),
(5158824, 750386, 91663, '<td valign="top">Lighting seems a little on-axis for my tastes--the dog has catchlights in the center of its eyes, which never looks all that great.</td>', 'Lighting seems a little on-axis for my tastes--the dog has catchlights in the center of its eyes, which never looks all that great.', '2008-12-30 23:48:27.000000', NULL, 1),
(5158825, 750821, 91663, '<td valign="top">Ooh, your bad luck to be the second of the same idea I''ve seen. But good skill for you--your lighting is far superior, so you get a better score. One niggling issue with the DOF on the fortune itself--would have been better if the whole fortune was in focus.</td>', 'Ooh, your bad luck to be the second of the same idea I''ve seen. But good skill for you--your lighting is far superior, so you get a better score. One niggling issue with the DOF on the fortune itself--would have been better if the whole fortune was in focus.', '2008-12-30 23:49:58.000000', NULL, 1),
(5158826, 750812, 91663, '<td valign="top">Very creative! Great colors, too.</td>', 'Very creative! Great colors, too.', '2008-12-30 23:50:11.000000', NULL, 1),
(5158827, 750386, 811, '<td valign="top">pugs always seem to look so anxious or nervous. . . good picture!</td>', 'pugs always seem to look so anxious or nervous. . . good picture!', '2008-12-30 23:50:12.000000', NULL, 1),
(5158828, 750673, 91663, '<td valign="top">No real central focus here--the seagulls drag my focus all over the picture, but with no real purpose or direction. Colors are also a little ho-hum.</td>', 'No real central focus here--the seagulls drag my focus all over the picture, but with no real purpose or direction. Colors are also a little ho-hum.', '2008-12-30 23:52:01.000000', NULL, 1),
(5158829, 750054, 91663, '<td valign="top">Fantastic lighting, expression, etc. Good job!</td>', 'Fantastic lighting, expression, etc. Good job!', '2008-12-30 23:52:31.000000', NULL, 1),
(5158832, 750721, 91663, '<td valign="top">This is, to too great an extent, just a picture of a work of art already made. The lighting/processing is interesting, but I just don''t really get much from it.</td>', 'This is, to too great an extent, just a picture of a work of art already made. The lighting/processing is interesting, but I just don''t really get much from it.', '2008-12-30 23:53:52.000000', NULL, 1),
(5158835, 750818, 91663, '<td valign="top">Lighting seems a little flat to me, with distracting imperfections on the background.</td>', 'Lighting seems a little flat to me, with distracting imperfections on the background.', '2008-12-30 23:55:09.000000', NULL, 1),
(5158836, 750718, 91663, '<td valign="top">Cute kid, good lighting, beautiful background. Only problem is it may be a little too beautiful--the sunburst is kinda distracting me from the real subject here.</td>', 'Cute kid, good lighting, beautiful background. Only problem is it may be a little too beautiful--the sunburst is kinda distracting me from the real subject here.', '2008-12-30 23:55:58.000000', NULL, 1),
(5158837, 750634, 91663, '<td valign="top">AHH!<br/> <br/>Awesome lighting here. Colors, too, are interesting.</td>', 'AHH! Awesome lighting here. Colors, too, are interesting.', '2008-12-30 23:56:33.000000', NULL, 1),
(5158843, 750787, 91663, '<td valign="top">Ah, wo ye shuo hanyu. Ta shi hen piaoliang!<br/> <br/>Mei nu is right, and so is the light/background. Excellent combo across the board. I''m just a little distracted by the catchlights in the middle of her eyes...Were your flashes triggered by the onboard flash? Either way, a few seconds of cloning would have brought this to 9 territory from me, but now you just get a lowly 8 :P</td>', 'Ah, wo ye shuo hanyu. Ta shi hen piaoliang! Mei nu is right, and so is the light/background. Excellent combo across the board. I''m just a little distracted by the catchlights in the middle of her eyes...Were your flashes triggered by the onboard flash? Either way, a few seconds of cloning would have brought this to 9 territory from me, but now you just get a lowly 8 :P', '2008-12-30 23:59:47.000000', NULL, 1),
(5158949, 750787, 80904, '<td valign="top">nice portrait but those eyes are way overdone they look freaky</td>', 'nice portrait but those eyes are way overdone they look freaky', '2008-12-31 00:26:48.000000', NULL, 1),
(5158951, 750759, 11518, '<td valign="top">That is some beautiful make-up work!</td>', 'That is some beautiful make-up work!', '2008-12-31 00:27:02.000000', NULL, 1),
(5158969, 750810, 8624, '<td valign="top">nice still life, but the background is too busy</td>', 'nice still life, but the background is too busy', '2008-12-31 00:31:17.000000', NULL, 1),
(5158978, 750615, 8624, '<td valign="top">I think if you have to explain this much in your title to tie a horse''s eye to "Asia" as a theme then you didn''t really accomplish much. It is a nice enough image, but it doesn''t say "Asia" to me</td>', 'I think if you have to explain this much in your title to tie a horse''s eye to "Asia" as a theme then you didn''t really accomplish much. It is a nice enough image, but it doesn''t say "Asia" to me', '2008-12-31 00:33:34.000000', NULL, 1),
(5158982, 750655, 8624, '<td valign="top">nice minimalist image, but the lighting could be improved. I don''t like the shadows and hot spots in the bowl.</td>', 'nice minimalist image, but the lighting could be improved. I don''t like the shadows and hot spots in the bowl.', '2008-12-31 00:35:45.000000', NULL, 1);
