INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5166817, 750757, 100646, '<td valign="top">This may just be me, but it looks like the edges of the pandas head kind of blend in with the backround. its a good shot though. I like how it is framed, the angle of the bamboo against the rock and the tree branch really makes you focus in on the pandas face.</td>', 'This may just be me, but it looks like the edges of the pandas head kind of blend in with the backround. its a good shot though. I like how it is framed, the angle of the bamboo against the rock and the tree branch really makes you focus in on the pandas face.', '2009-01-03 04:21:59.000000', NULL, 1),
(5166820, 750760, 100646, '<td valign="top">its a cool scene, but I dont like how soft it is. The only thing that stands out to me is that bright pink tongue.</td>', 'its a cool scene, but I dont like how soft it is. The only thing that stands out to me is that bright pink tongue.', '2009-01-03 04:27:45.000000', NULL, 1),
(5166832, 750727, 100646, '<td valign="top">This is a great photo. Its a picture of plated food that doesnt make me feel like I''m deciding what to order for lunch. The chopsticks going off to the right also makes the eye wander around the image so that I didnt just keep staring at the delicious looking sashimi =)</td>', 'This is a great photo. Its a picture of plated food that doesnt make me feel like I''m deciding what to order for lunch. The chopsticks going off to the right also makes the eye wander around the image so that I didnt just keep staring at the delicious looking sashimi =)', '2009-01-03 04:34:31.000000', NULL, 1),
(5166833, 750674, 100646, '<td valign="top">The makeup looks cakey and unevenly applied. Also, this photo doesnt capture the model with much expression.</td>', 'The makeup looks cakey and unevenly applied. Also, this photo doesnt capture the model with much expression.', '2009-01-03 04:37:01.000000', NULL, 1),
(5166834, 750711, 100646, '<td valign="top">whats that cat doing?</td>', 'whats that cat doing?', '2009-01-03 04:38:34.000000', NULL, 1),
