(5172817, 750782, 67697, '<td valign="top">too bad he did not have Godzilla jammies on - I think that would have sealed the deal for most.  I thought it was funny.  Maybe some of the voters have never watched kids do this - I know mine have!</td>', 'too bad he did not have Godzilla jammies on - I think that would have sealed the deal for most.  I thought it was funny.  Maybe some of the voters have never watched kids do this - I know mine have!', '2009-01-05 13:39:25.000000', NULL, 0),
(5172819, 750454, 68504, '<td valign="top">Once again posthumous speaks for the picture: "That face, that face, that fabulous face!  Those fruit, those fruit..."<br/> <br/>(Never would have thought this yours; shouldn''t surprise me though that your sense of colour rivals your feel for black and white.  Congratulations on all counts, including a working SD card!)</td>', 'Once again posthumous speaks for the picture: "That face, that face, that fabulous face!  Those fruit, those fruit..." (Never would have thought this yours; shouldn''t surprise me though that your sense of colour rivals your feel for black and white.  Congratulations on all counts, including a working SD card!)', '2009-01-05 13:40:25.000000', NULL, 0),
(5172820, 750820, 67697, '<td valign="top">lol is that what these are called?  we have these in a field near here I think.  the bokeh is gorgeous.</td>', 'lol is that what these are called?  we have these in a field near here I think.  the bokeh is gorgeous.', '2009-01-05 13:40:27.000000', NULL, 0),
(5172827, 750150, 67697, '<td valign="top">This looks like it would make a great stained-glass piece.  Can you imagine what it would look like with the sun shining thru it?  Did you really take this at night?  The blue is gorgeous.</td>', 'This looks like it would make a great stained-glass piece.  Can you imagine what it would look like with the sun shining thru it?  Did you really take this at night?  The blue is gorgeous.', '2009-01-05 13:42:07.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5172833, 750530, 67697, '<td valign="top">I was hoping your comments would tell me what this is.  I''ve never seen anything like it before.  I see the stairs.  Are they for an observation deck or just to clean the glass?  :)</td>', 'I was hoping your comments would tell me what this is.  I''ve never seen anything like it before.  I see the stairs.  Are they for an observation deck or just to clean the glass?  :)', '2009-01-05 13:43:54.000000', NULL, 0),
(5172847, 750118, 68504, '<td valign="top">I think this is my favourite of the "faces" entry; love the concept but I also think I agree with posthumous about the lighting: would love to see more of a blend of face with koi. Kudos to Tiffany.</td>', 'I think this is my favourite of the "faces" entry; love the concept but I also think I agree with posthumous about the lighting: would love to see more of a blend of face with koi. Kudos to Tiffany.', '2009-01-05 13:45:37.000000', NULL, 0),
(5172848, 750792, 67697, '<td valign="top">Uh oh I am a slacker - did not get to this fast enough lol.  I''ll have to look up your title lol.  It would have been fun to see some of these in the "personification" challenge.  Some of the balls look like they have open mouths.  Pretty cool!</td>', 'Uh oh I am a slacker - did not get to this fast enough lol.  I''ll have to look up your title lol.  It would have been fun to see some of these in the "personification" challenge.  Some of the balls look like they have open mouths.  Pretty cool!', '2009-01-05 13:45:41.000000', NULL, 0),
(5172910, 750386, 52549, '<td valign="top">Great shot, Linda. Bernhard Victor Christoph Carl von Bülow, more commonly known under the pseudonym Loriot, is a German humorist, graphic artist, film director, actor and writer. He is also a great pugs fan and once said "a life without pugs is possible but meaningless". Every time I see one of your pug shots I always think of this ;-)</td>', 'Great shot, Linda. Bernhard Victor Christoph Carl von Bülow, more commonly known under the pseudonym Loriot, is a German humorist, graphic artist, film director, actor and writer. He is also a great pugs fan and once said "a life without pugs is possible but meaningless". Every time I see one of your pug shots I always think of this ;-)', '2009-01-05 14:14:05.000000', NULL, 0),
(5172912, 750821, 1031, '<td valign="top">Good idea, well-executed! I need to buy myself a bag of those ... ;-)</td>', 'Good idea, well-executed! I need to buy myself a bag of those ... ;-)', '2009-01-05 14:15:21.000000', NULL, 0),
(5172915, 750777, 1031, '<td valign="top">Good idea. The lighting seems just a bit harsh, but that does provide good clarity and focus.</td>', 'Good idea. The lighting seems just a bit harsh, but that does provide good clarity and focus.', '2009-01-05 14:17:07.000000', NULL, 0),
